	key               *string
	body              *string
	channel_key       *string
	thread_key        *string
	author_person_key *string
	sent_at           *time.Time
	summary           *string
	search_text       *string
	source            *string
	source_instance   *string
	external_id       *string
	source_url        *string
	freshness_state   *message.FreshnessState
	visibility        *message.Visibility
	confidence        *float64
